    });
    // No verified hash anywhere → the source block is omitted,
    // never written as the schema-invalid empty string (#243).
    expect(doc!.sourceAudio).toBeNull();
  });
});

/**
 * Build the `.hornscribe.json` project document (schema v1, FND-001)
 * for the プロジェクトを保存 command (#100).
 *
 * The worker's `project.save` validates this through
 * HornScribeProject.from_dict before writing, so every id here must
 * already satisfy the domain regexes (prj-/rev-/tr-/sn-). Fields the
 * schema does not know (scoreDocument, musicXmlConcert, musicXmlHornF,
 * reviewIssues) ride along as extra keys — preserved verbatim, ignored
 * by the v1 validator, and the data a future project-open restore
 * needs to reconstruct the score without re-transcribing.
 */
import type { LoadedAudio } from "./types";
import type { ScoreDocumentPort } from "../score/document";

/** Fields the app knows at save time. */
export interface ProjectSaveInput {
  readonly audio: LoadedAudio | null;
  readonly doc: ScoreDocumentPort;
  /** Completed job result payload (meta/reviewIssues/scoreDocument). */
  readonly result: unknown;
  /** #222: when re-saving an opened project, keep its identity — a
   *  fresh save derives a new prj- id from the source identity. */
  readonly projectId?: string | null;
  /** #265: the project's recorded source ref — the fallback when no
   *  audio is loaded (SOURCE_MISSING save must not erase the
   *  originalPath/contentHash a later relink verifies against). */
  readonly priorSourceAudio?: {
    originalPath: string;
    contentHash: string;
  } | null;
}

/** `prj-<16hex>` — deterministic content-derived id (ids.py contract). */
export async function deriveProjectId(seed: unknown): Promise<string> {
  // Callers pass a flat object built in fixed key order — plain
  // stringify is deterministic here (same policy as ids.py's canonical
  // JSON digest, minus key sorting which a flat fixed-order object
  // does not need).
  const blob = JSON.stringify(seed);
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(blob),
  );
  const hex = [...new Uint8Array(digest)]
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
  return `prj-${hex.slice(0, 16)}`;
}

function resultMeta(result: unknown): Record<string, unknown> {
  if (typeof result !== "object" || result === null) return {};
  const meta = (result as Record<string, unknown>).meta;
  return typeof meta === "object" && meta !== null
    ? (meta as Record<string, unknown>)
    : {};
}

/** Source ref for the audio backing this score (path-backed only —
 *  browser-dev File refs have no durable path to record). */
function sourceAudioOf(audio: LoadedAudio | null): {
  originalPath: string;
  contentHash: string;
} | null {
  if (!audio) return null;
  const ref = audio.ref;
  if (ref.kind === "path") {
    return { originalPath: ref.path, contentHash: ref.contentHash ?? "" };
  }
  if (ref.kind === "recording" && ref.path) {
    return { originalPath: ref.path, contentHash: ref.contentHash ?? "" };
  }
  return null;
}

const REVISION_RE = /^rev-[0-9a-f]{16}$/;
const TRANSCRIPTION_RE = /^tr-[0-9a-f]{16}$/;
const SCORE_NOTE_RE = /^sn-\d{6}$/;

/** True when the document's ids satisfy the v1 schema — a fixture/dev
 *  document (rev-fixture*) cannot be saved and the command should say
 *  so honestly instead of shipping an invalid file. */
export function isSaveableRevision(revisionId: string): boolean {
  return REVISION_RE.test(revisionId);
}

/**
 * Assemble the schema-v1 document. Returns null when the score cannot
 * be represented (non-schema revision id — e.g. the dev fixture doc).
 */
export async function buildProjectDocument(
  input: ProjectSaveInput,
): Promise<Record<string, unknown> | null> {
  const { audio, doc, result } = input;
  if (!isSaveableRevision(doc.revisionId)) return null;
  const meta = resultMeta(result);
  // #243: the engine already streamed a SHA-256 of the source into
  // the canonical payload — prefer that provenance over re-hashing
  // the browser-held bytes a second time.
  const canonical = doc.canonicalDocument?.() as
    Record<string, unknown> | undefined;
  const canonicalHash =
    typeof canonical?.sourceAudioHash === "string"
      ? (canonical.sourceAudioHash as string)
      : null;
  const sourceAudio = sourceAudioOf(audio);
  // #243: never write an empty contentHash — a project saved without
  // a verified source identity cannot reopen or relink. Prefer the
  // engine-recorded hash, then the import-time hash; if neither
  // exists the sourceAudio block is omitted rather than written
  // invalid.
  const sourceAudioResolved =
    sourceAudio == null
      ? // #265: no audio loaded (SOURCE_MISSING) — keep the project's
        // recorded ref so a save does not erase the relink target.
        input.priorSourceAudio &&
        (canonicalHash ?? input.priorSourceAudio.contentHash)
        ? {
            originalPath: input.priorSourceAudio.originalPath,
            contentHash: (canonicalHash ??
              input.priorSourceAudio.contentHash) as string,
          }
        : null
      : (canonicalHash ?? sourceAudio.contentHash)
        ? {
            originalPath: sourceAudio.originalPath,
            contentHash: (canonicalHash ?? sourceAudio.contentHash) as string,
          }
        : null;

  const transcriptionRevision = meta.transcriptionRevision;
  const transcription =
    typeof transcriptionRevision === "string" &&
    TRANSCRIPTION_RE.test(transcriptionRevision)
      ? {
          backend: String(meta.backend ?? "unknown"),
          backendVersion: String(meta.backendVersion ?? "unknown"),
          settings:
            typeof meta.settings === "object" && meta.settings !== null
              ? meta.settings
              : {},
          revision: transcriptionRevision,
          rawResultRef: `raw/${transcriptionRevision}.json`,
        }
      : null;

  // Canonical-note edits → schema UserEdit records. pitchDelta and
  // deleted are independent facets, so one UI edit can emit two rows.
  const userEdits: Record<string, unknown>[] = [];
  let editSeq = 0;
  for (const [noteId, edit] of doc.noteEdits()) {
    if (!SCORE_NOTE_RE.test(noteId)) continue;
    if (edit.pitchDelta !== 0) {
      userEdits.push({
        id: `ue-${String(++editSeq).padStart(4, "0")}`,
        scoreRevision: doc.revisionId,
        kind: "pitch_change",
        targetNoteIds: [noteId],
        payload: { semitones: edit.pitchDelta },
      });
    }
    if (edit.deleted) {
      userEdits.push({
        id: `ue-${String(++editSeq).padStart(4, "0")}`,
        scoreRevision: doc.revisionId,
        kind: "delete",
        targetNoteIds: [noteId],
        payload: {},
      });
    }
  }

  const reviewDecisions = doc
    .reviewIssues()
    .filter((i) => i.status !== "open")
    .map((i) => ({
      issueId: i.id,
      scoreRevision: doc.revisionId,
      status: i.status,
      note: null,
    }));

  // #222: a project's identity is its source, not the current score
  // revision — edits must not mint a new project id. Re-saving an
  // opened project keeps its recorded id verbatim.
  const projectId =
    input.projectId ??
    (await deriveProjectId({
      audioPath: sourceAudioResolved?.originalPath ?? null,
      audioHash: sourceAudioResolved?.contentHash ?? null,
      title: doc.meta.title,
    }));

  const resultObj =
    typeof result === "object" && result !== null
      ? (result as Record<string, unknown>)
      : {};

  return {
    schemaVersion: 1,
    projectId,
    sourceAudio: sourceAudioResolved,
    transcription,
    score: {
      revision: doc.revisionId,
      // The score body travels inline (below); this ref names the
      // canonical cache location a future store would write it to.
      scoreRef: `scores/${doc.revisionId}.json`,
      quantizationSettings:
        typeof meta.settings === "object" && meta.settings !== null
          ? meta.settings
          : {},
    },
    userEdits,
    reviewDecisions,
    uiSession: null,
    // --- preserved extras (ignored by the v1 validator) ---
    // #115: the LIVE canonical payload — after an engine rhythm edit the
    // document's scoreDocument is newer than the job result's, and saving
    // the stale one would lose the edit on reopen (the XMLs below are
    // already the edited bodies).
    scoreDocument: doc.canonicalDocument?.() ?? resultObj.scoreDocument ?? null,
    reviewIssues: doc.reviewIssues(),
    musicXmlConcert: doc.musicXml("concert"),
    musicXmlHornF: doc.musicXml("hornF"),
    meta,
  };
}

/**
 * 要確認 review header (UI-050, GUI_UX_SPEC §12).
 *
 * Spec header: 「要確認 n / total」＋ [前へ] [元音源を再生] [問題なし]
 * [次へ]. The P4 prototype's validated flow is productionized here: every
 * action is a real button (Tab/Enter reachable) AND a registry-bound
 * shortcut shown in the tooltip — 20+ items are processable without ever
 * opening a menu.
 *
 * Visual rule (issue body + §12/§15): the review state is expressed by a
 * text badge (要確認 + severity label), the reason's Japanese title/detail
 * and the position counter — never by color alone and never by a raw
 * confidence number (モデル確信度 is shown only as labelled evidence).
 */
import { ja } from "../strings/ja";
import { HsButton } from "../components/primitives/Button";
import { HsTooltip } from "../components/primitives/Tooltip";
import { issueConfidence, type ScoreReviewIssue } from "./review";

export interface ReviewBarCopy {
  reasonTitle: string;
  reasonDetail: string;
  severityLabel: string;
  statusLabel: string;
}

export interface ReviewBarProps {
  /** Current cursor (0-based) into the full issue list. */
  readonly index: number;
  /** Total issues in this revision's list. */
  readonly total: number;
  /** Issues still open. */
  readonly pending: number;
  /** #272: issues the engine detected but the surfacing cap omitted —
   *  shown so a truncated list is never silent (0 = hide). */
  readonly omitted?: number;
  readonly issue: ScoreReviewIssue | null;
  readonly copy: ReviewBarCopy | null;
  /** True when the focused issue's primary note is currently deleted. */
  readonly noteDeleted: boolean;
  readonly canUndo: boolean;
  readonly canRedo: boolean;
  /** #148: optional one-click action for issues that carry a direct
   *  remedy (e.g. the voices-texture retry on a detected mix). */
  readonly actionLabel?: string | null;
  readonly onAction?: () => void;
  onPrev(): void;
  onNext(): void;
  onPlaySource(): void;
  onAccept(): void;
  onDismiss(): void;
  onPitch(delta: number): void;
  onDeleteOrRestore(): void;
  onUndo(): void;
  onRedo(): void;
  onExit(): void;
}

function withKey(label: string, key: string): string {
  return `${label}（${key}）`;
}

export function ReviewBar({
  index,
  total,
  pending,
  omitted = 0,
  issue,
  copy,
  noteDeleted,
  canUndo,
  canRedo,
  actionLabel = null,
  onAction,
  onPrev,
  onNext,
  onPlaySource,
  onAccept,
  onDismiss,
  onPitch,
  onDeleteOrRestore,
  onUndo,
  onRedo,
  onExit,
}: ReviewBarProps) {
  const r = ja.review;
  const allDone = pending === 0;
  const confidence = issue ? issueConfidence(issue) : null;
  return (
    <div
      className="hs-score-reviewbar"
      role="region"
      aria-label={r.regionLabel}
    >
      <div className="hs-score-reviewbar__row hs-score-reviewbar__row--status">
        <strong className="hs-score-reviewbar__position" aria-live="polite">
          {allDone ? r.allDone : r.position(index + 1, total)}
        </strong>
        {!allDone && (
          <span className="hs-score-reviewbar__remaining">
            {r.remaining(pending)}
          </span>
        )}
        {omitted > 0 && (
          <span className="hs-score-reviewbar__omitted">
            {r.omitted(omitted)}
          </span>
        )}
        {issue && copy && (
          <>
            <span className="hs-score-reviewbar__badge">
              {ja.reviewBadge.needsReview}
            </span>
            <span className="hs-score-reviewbar__reason">
              {copy.reasonTitle}
            </span>
            <span className="hs-score-reviewbar__detail">
              {copy.reasonDetail}
            </span>
            <span className="hs-score-reviewbar__meta">
              {copy.severityLabel}・{copy.statusLabel}
              {confidence != null &&
                `・${r.confidence(Math.round(confidence * 100))}`}
            </span>
          </>
        )}
      </div>
      <div
        className="hs-score-reviewbar__row"
        role="toolbar"
        aria-label={r.actionsLabel}
      >
        <HsTooltip content={withKey(ja.common.prev, "←")}>
          <HsButton size="small" disabled={total === 0} onClick={onPrev}>
            {ja.common.prev}
          </HsButton>
        </HsTooltip>
        <HsTooltip content={withKey(r.playSource, "R")}>
          <HsButton
            size="small"
            disabled={issue == null}
            onClick={onPlaySource}
          >
            {r.playSource}
          </HsButton>
        </HsTooltip>
        {actionLabel && onAction ? (
          <HsTooltip content={r.retranscribeVoicesTip}>
            <HsButton size="small" onClick={onAction}>
              {actionLabel}
            </HsButton>
          </HsTooltip>
        ) : null}
        <HsTooltip content={withKey(r.markOk, "O")}>
          <HsButton
            size="small"
            variant="primary"
            disabled={issue == null}
            onClick={onAccept}
          >
            {r.markOk}
          </HsButton>
        </HsTooltip>
        <HsTooltip content={withKey(r.dismiss, "Shift+O")}>
          <HsButton size="small" disabled={issue == null} onClick={onDismiss}>
            {r.dismiss}
          </HsButton>
        </HsTooltip>
        <HsTooltip content={withKey(r.pitchUp, "Alt+↑")}>
          <HsButton
            size="small"
            disabled={issue == null}
            onClick={() => onPitch(1)}
          >
            {r.pitchUp}
          </HsButton>
        </HsTooltip>
        <HsTooltip content={withKey(r.pitchDown, "Alt+↓")}>
          <HsButton
            size="small"
            disabled={issue == null}
            onClick={() => onPitch(-1)}
          >
            {r.pitchDown}
          </HsButton>
        </HsTooltip>
        <HsTooltip content={withKey(r.deleteNote, "Delete")}>
          <HsButton
            size="small"
            disabled={issue == null}
            onClick={onDeleteOrRestore}
          >
            {noteDeleted ? r.restoreNote : r.deleteNote}
          </HsButton>
        </HsTooltip>
        <HsTooltip content={withKey(r.undo, "Ctrl+Z")}>
          <HsButton size="small" disabled={!canUndo} onClick={onUndo}>
            {r.undo}
          </HsButton>
        </HsTooltip>
        <HsTooltip content={withKey(r.redo, "Ctrl+Shift+Z")}>
          <HsButton size="small" disabled={!canRedo} onClick={onRedo}>
            {r.redo}
          </HsButton>
        </HsTooltip>
        <HsTooltip content={withKey(ja.common.next, "→")}>
          <HsButton size="small" disabled={total === 0} onClick={onNext}>
            {ja.common.next}
          </HsButton>
        </HsTooltip>
        <span className="hs-score-reviewbar__spacer" />
        <HsTooltip content={withKey(r.exit, "Esc")}>
          <HsButton size="small" onClick={onExit}>
            {r.exit}
          </HsButton>
        </HsTooltip>
      </div>
      {!allDone && (
        <div className="hs-score-reviewbar__row hs-score-reviewbar__row--hint">
          <span className="hs-score-reviewbar__hint">{r.hint}</span>
        </div>
      )}
    </div>
  );
}

/**
 * UI-030 — production score workspace (SCORE_READY+, GUI_UX_SPEC §6–§11).
 *
 * Verovio-based SVG rendering driven by a `ScoreDocumentPort` (fixture
 * adapter today; engine data slots in later). Responsibilities:
 *
 * - render MusicXML → SVG pages (inlined WASM, fully offline);
 * - note click → canonical `sn-*` selection → properties inspector;
 * - Concert ↔ F管ホルン switch preserving selection, transport position,
 *   loop, playback state, zoom and an equivalent viewport position
 *   (UI-005 verified semantics);
 * - playback hierarchy: caret → current-measure wash → active-note outline,
 *   all DOM-only marks — zero `renderToSVG` on the frame path;
 * - follow playback with manual-scroll suspension + explicit 追従を再開;
 * - review 要確認 markers (dotted cue, warning tint — never error red);
 * - zoom controls bound to the same methods the registry commands call.
 */
